using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Windows.Forms;
using System.Web.Script.Serialization;

static class StudioTests {
 static void Require(bool b){if(!b)throw new Exception("Comprobación fallida");}
 static void Field(object target,string name,object value){target.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(target,value);}
 static object Call(object target,string name,params object[] values){try{return target.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(target,values);}catch(TargetInvocationException e){throw e.InnerException??e;}}
 static EngineSession ReadyEngine(){var engine=new EngineSession(s=>{},()=>{},p=>{});Field(engine,"running",true);Field(engine,"selectionReady",true);Field(engine,"selectedId",FirmwareFile.Product);Field(engine,"selectedVersion","2.50.0");return engine;}
 static FirmwareFile CustomFixture(){return new FirmwareFile{Hash=PortableRuntime.CustomHash,Version="02.50.00",Summary="Archivo de prueba local",PathName="fixture.hxf"};}
 static string BackupFixture(string folder){string file=Path.Combine(folder,"synthetic-header-only-backup.pgb");byte[] data=new byte[128];Buffer.BlockCopy(BitConverter.GetBytes(0x4c364641U),0,data,0,4);Buffer.BlockCopy(BitConverter.GetBytes(FirmwareFile.Product),0,data,24,4);File.WriteAllBytes(file,data);return file;}
 static IEnumerable<Control> Descendants(Control root){foreach(Control child in root.Controls){yield return child;foreach(var sub in Descendants(child))yield return sub;}}
 static StudioFirmwarePane PreparedPane(string folder,bool official=false){var pane=new StudioFirmwarePane(false);Field(pane,"engine",ReadyEngine());Call(pane,"ShowFirmware",official?new FirmwareFile{IsOfficial=true,Hash=FirmwareFile.OfficialHash}:CustomFixture());Call(pane,"SetBackup",BackupFixture(folder));Require(pane.InstallEnabled);return pane;}
 static void Reject(Action a){bool rejected=false;try{a();}catch(IOException){rejected=true;}Require(rejected);}
 static void Pump(Task t){var until=DateTime.UtcNow.AddSeconds(10);while(!t.IsCompleted&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(1);}Require(t.IsCompleted);t.GetAwaiter().GetResult();}
 public static int Run(string source,string bank,string folder){Directory.CreateDirectory(folder);StudioUsbGate.UseTestLock(Path.Combine(folder,"fixture-device.lock"));var results=new List<object>();int failed=0;
  Action<string,Action> test=(name,body)=>{try{body();results.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;results.Add(new{name=name,status="FAIL",error=e.ToString()});}};
  test("exclusive_between_firmware_and_nam",()=>{using(StudioUsbGate.Acquire("Firmware")){Require(StudioUsbGate.Owner=="Firmware");Reject(()=>StudioUsbGate.Acquire("NAM"));}Require(StudioUsbGate.Owner=="");using(StudioUsbGate.Acquire("NAM"))Require(StudioUsbGate.Owner=="NAM");});
  test("lease_releases_after_exception_and_double_dispose",()=>{IDisposable old=null;try{using(old=StudioUsbGate.Acquire("Fallo simulado"))throw new IOException("Fixture");}catch(IOException){}old.Dispose();using(StudioUsbGate.Acquire("Reintento"))Require(StudioUsbGate.Owner=="Reintento");});
  test("lease_can_close_on_another_thread",()=>{var lease=StudioUsbGate.Acquire("STA simulado");var task=Task.Run(()=>lease.Dispose());task.GetAwaiter().GetResult();Require(StudioUsbGate.Owner=="");});
  test("second_process_cannot_open_device_lease",()=>{string path=Path.Combine(folder,"fixture-device.lock");var info=new ProcessStartInfo(Application.ExecutablePath,"--lease-child \""+path+"\""){UseShellExecute=false,CreateNoWindow=true};using(StudioUsbGate.Acquire("Proceso padre"))using(var child=Process.Start(info)){Require(child.WaitForExit(20000)&&child.ExitCode==17);}using(var child=Process.Start(info)){Require(child.WaitForExit(20000)&&child.ExitCode==0);}});
  test("blocked_nam_never_opens_its_transport",()=>{int calls=0;var fixture=new NamFixtureDevice();var app=new NamDataSession(Path.Combine(folder,"blocked-nam"),s=>{},(p,log)=>{calls++;return new PodWireSession(new NamWireFixture(fixture),log);});using(StudioUsbGate.Acquire("Firmware"))Reject(()=>app.Connect().GetAwaiter().GetResult());Require(calls==0&&!app.Connected);app.Connect().GetAwaiter().GetResult();Require(calls==1&&app.Connected);app.Disconnect().GetAwaiter().GetResult();Require(StudioUsbGate.Owner=="");});
  test("failed_transport_does_not_retain_lease",()=>{var app=new NamDataSession(Path.Combine(folder,"failed-transport"),s=>{},(p,log)=>{throw new IOException("Fallo fixture antes de abrir");});Reject(()=>app.Connect().GetAwaiter().GetResult());using(StudioUsbGate.Acquire("Siguiente apartado"))Require(!app.Connected);});
  test("unconfirmed_sdk_shutdown_keeps_nam_locked",()=>{using(var pane=new StudioFirmwarePane(true)){var engine=new EngineSession(s=>{},()=>{},p=>{});Field(engine,"usbClosed",false);Field(pane,"engine",engine);Field(pane,"lease",StudioUsbGate.Acquire("Motor sin cierre confirmado"));Reject(()=>pane.ReleaseAsync().GetAwaiter().GetResult());Require(StudioUsbGate.Owner=="Motor sin cierre confirmado");Reject(()=>StudioUsbGate.Acquire("NAM"));Field(engine,"usbClosed",true);pane.ReleaseAsync().GetAwaiter().GetResult();Require(StudioUsbGate.Owner=="");}});
  test("unified_startup_and_navigation_do_not_open_usb",()=>{foreach(bool preview in new[]{false,true})using(var window=new StudioWindow(preview,preview?source:null,preview?bank:null)){Require(window.FirmwareVisible&&!window.InstallEnabled&&!window.IsBusy&&StudioUsbGate.Owner=="");Require(window.SelectSectionAsync(false).GetAwaiter().GetResult()&&!window.FirmwareVisible&&!window.InstallEnabled&&StudioUsbGate.Owner=="");Require(window.SelectSectionAsync(true).GetAwaiter().GetResult()&&window.FirmwareVisible&&!window.InstallEnabled&&StudioUsbGate.Owner=="");}});
  test("footer_links_to_conr4d_repositories_without_opening_browser",()=>{using(var window=new StudioWindow(true)){var credit=window.Controls.Find("Conr4dGithub",true).Single() as LinkLabel;Require(credit!=null&&credit.Text=="Developed by Conr4d"&&(string)credit.Tag=="https://github.com/conr4d86?tab=repositories");}});
  test("connected_and_selected_firmware_replaces_stale_opening_message",()=>{using(var pane=new StudioFirmwarePane(false)){Field(pane,"engine",ReadyEngine());Call(pane,"ShowFirmware",CustomFixture());var label=(Label)typeof(StudioFirmwarePane).GetField("state",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(pane);label.Text="Abriendo el motor integrado…";Call(pane,"UpdateUi");Require(pane.ConnectionMarked&&pane.CustomMarked&&!pane.OfficialMarked&&!pane.BackupMarked&&!pane.InstallEnabled);Require(!pane.StatusText.Contains("Abriendo")&&pane.StatusText.Contains("backup PGB"));}});
  test("official_and_custom_selections_are_mutually_marked",()=>{using(var pane=new StudioFirmwarePane(false)){Call(pane,"ShowFirmware",CustomFixture());Call(pane,"UpdateUi");Require(pane.CustomMarked&&!pane.OfficialMarked);Call(pane,"ShowFirmware",new FirmwareFile{Hash=FirmwareFile.OfficialHash,IsOfficial=true,Summary="Fixture oficial"});Call(pane,"UpdateUi");Require(pane.OfficialMarked&&!pane.CustomMarked);}});
  test("backup_precaution_is_distinct_from_official_restore_information",()=>{var custom=InstallNotice.For(CustomFixture());var official=InstallNotice.For(new FirmwareFile{IsOfficial=true});Require(custom.Icon==MessageBoxIcon.Warning&&custom.Text.Contains("backup con POD Go Edit")&&official.Icon==MessageBoxIcon.Information&&official.Text.Contains("carga tu backup desde POD Go Edit")&&!official.Text.Contains("error"));});
  test("cancelled_precaution_never_dispatches_firmware",()=>{using(var pane=PreparedPane(folder)){int confirmations=0,writes=0;Call(pane,"RequestInstall",new Func<InstallNotice,bool>(n=>{confirmations++;Require(pane.IsBusy&&!pane.InstallEnabled);return false;}),new Action<FirmwareFile,string>((f,b)=>writes++));Require(confirmations==1&&writes==0&&!pane.IsBusy&&pane.InstallEnabled&&pane.StatusText=="Operación cancelada.");}});
  test("accepted_precaution_dispatches_exactly_selected_file_and_backup",()=>{using(var pane=PreparedPane(folder)){var selected=(FirmwareFile)typeof(StudioFirmwarePane).GetField("firmware",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(pane);int writes=0;Call(pane,"RequestInstall",new Func<InstallNotice,bool>(n=>true),new Action<FirmwareFile,string>((f,b)=>{writes++;Require(ReferenceEquals(selected,f)&&File.Exists(b));}));Require(writes==1&&!pane.IsBusy);}});
  test("selection_changed_during_precaution_cannot_be_written",()=>{using(var pane=PreparedPane(folder)){int writes=0;bool rejected=false;try{Call(pane,"RequestInstall",new Func<InstallNotice,bool>(n=>{Call(pane,"ShowFirmware",CustomFixture());return true;}),new Action<FirmwareFile,string>((f,b)=>writes++));}catch(InvalidOperationException){rejected=true;}Require(rejected&&writes==0&&!pane.IsBusy);}});
  test("official_restore_confirmation_dispatches_only_after_ok",()=>{using(var pane=PreparedPane(folder,true)){int writes=0;Call(pane,"RequestInstall",new Func<InstallNotice,bool>(n=>{Require(n.Icon==MessageBoxIcon.Information);return true;}),new Action<FirmwareFile,string>((f,b)=>{Require(f.IsOfficial);writes++;}));Require(writes==1);}});
  test("simplified_firmware_interface_has_large_steps_and_two_selectors",()=>{using(var pane=new StudioFirmwarePane(true)){var controls=Descendants(pane).ToArray();var steps=controls.OfType<Label>().Where(c=>c.Text.StartsWith("01 ")||c.Text.StartsWith("02 ")||c.Text.StartsWith("03 ")).ToArray();Require(steps.Length==3&&steps.All(c=>c.Font.Bold&&c.Font.Size>=14));var buttons=controls.OfType<Button>().Select(c=>c.Text).ToArray();Require(buttons.Contains("CF NAM Conr4d")&&buttons.Contains("Cargar Firmware Oficial…")&&buttons.Contains("Carga tu backup (.pgb)…")&&!buttons.Contains("Abrir HXF…")&&!buttons.Contains("Oficial 2.50"));Require(!controls.OfType<Label>().Any(c=>c.Text.Contains("SHA256")||c.Text.Contains("Fletcher")));}});
  test("official_file_picker_rejects_a_custom_hxf",()=>{PortableRuntime.Prepare();using(var pane=new StudioFirmwarePane(false)){Pump((Task)Call(pane,"LoadFirmware",PortableRuntime.Custom));Require(!pane.CustomMarked&&!pane.OfficialMarked&&!pane.InstallEnabled&&pane.StatusText.Contains("firmware oficial"));}});
  test("engine_percentage_below_one_is_not_multiplied",()=>{var observed=new List<double>();var e=new EngineSession(s=>{},()=>{},v=>observed.Add(v));Call(e,"Event","stepsSystemState","engineProgress",0.6897F,false);Call(e,"Event","stepsSystemState","stageProgress",0.99F,false);Call(e,"Event","stepsSystemState","engineProgress",101.0,false);Require(observed.Count==2&&Math.Abs(observed[0]-0.6897)<0.00001&&observed[1]==100);});
  test("sdk_startup_error_stays_visible_in_red",()=>{using(var pane=new StudioFirmwarePane(true)){Call(pane,"Log","ERROR MOTOR simulated startup failure");Call(pane,"UpdateUi");var label=(Label)typeof(StudioFirmwarePane).GetField("state",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(pane);Require(pane.StatusText.Contains("No se pudo")&&label.ForeColor==System.Drawing.Color.Salmon);}});
  test("short_name_preview_combines_selected_model_and_user_name",()=>{using(var window=new StudioWindow(true,source,bank)){Require(window.SelectSectionAsync(false).GetAwaiter().GetResult());var view=(NamWindow)typeof(StudioWindow).GetField("nam",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window);view.SelectPreviewModel(53);var editor=(TextBox)Descendants(view).Single(c=>c.Name=="NamShortName");editor.Text="FRIEDMAN HBE";var label=(Label)typeof(NamWindow).GetField("summary",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(view);Require(editor.MaxLength==14&&label.Text.Contains("53. FRIEDMAN HBE")&&!window.IsBusy&&!window.InstallEnabled);}});
  test("verified_backup_completes_preparation_without_installing",()=>{string sourceBackup=Path.Combine(folder,"synthetic-header-only-backup.pgb");byte[] data=new byte[128];Buffer.BlockCopy(BitConverter.GetBytes(0x4c364641U),0,data,0,4);Buffer.BlockCopy(BitConverter.GetBytes(FirmwareFile.Product),0,data,24,4);File.WriteAllBytes(sourceBackup,data);using(var pane=new StudioFirmwarePane(false)){Field(pane,"engine",ReadyEngine());Call(pane,"ShowFirmware",CustomFixture());Call(pane,"SetBackup",sourceBackup);Require(pane.BackupMarked&&pane.ConnectionMarked&&pane.CustomMarked&&pane.InstallEnabled&&pane.StatusText.Contains("Todo preparado"));Field(pane,"engine",null);Call(pane,"UpdateUi");Require(!pane.ConnectionMarked&&!pane.InstallEnabled&&pane.BackupMarked&&!pane.StatusText.Contains("Todo preparado"));}});
  test("failed_file_validation_clears_previous_firmware_mark",()=>{string bad=Path.Combine(folder,"invalid-for-selection.hxf");File.WriteAllText(bad,"not firmware");using(var pane=new StudioFirmwarePane(false)){Call(pane,"ShowFirmware",CustomFixture());Call(pane,"UpdateUi");Require(pane.CustomMarked);Pump((Task)Call(pane,"LoadFirmware",bad));Require(!pane.CustomMarked&&!pane.OfficialMarked&&!pane.InstallEnabled);string error=pane.StatusText;Call(pane,"UpdateUi");Require(error==pane.StatusText&&error.Length>0&&!error.Contains("Abriendo"));}});
  test("progress_and_terminal_result_survive_readiness_refresh",()=>{using(var pane=new StudioFirmwarePane(false)){var engine=ReadyEngine();Field(pane,"engine",engine);Field(engine,"transferring",true);var label=(Label)typeof(StudioFirmwarePane).GetField("state",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(pane);label.Text="Instalando · 37.50 %";Call(pane,"UpdateUi");Require(pane.StatusText=="Instalando · 37.50 %");Field(engine,"transferring",false);Call(pane,"Log","TRANSFERENCIA COMPLETADA. Fixture sin USB");Call(pane,"UpdateUi");Require(pane.StatusText.StartsWith("Transferencia completada."));Call(pane,"Log","ACTUALIZACIÓN FALLIDA: Fixture sin USB");Call(pane,"UpdateUi");Require(pane.StatusText.StartsWith("Instalación fallida."));}});
  test("nam_operation_blocks_tab_change_and_window_close",()=>{using(var window=new StudioWindow(true,source,bank)){Require(window.SelectSectionAsync(false).GetAwaiter().GetResult());window.ShowInTaskbar=false;window.StartPosition=FormStartPosition.Manual;window.Location=new System.Drawing.Point(-25000,-25000);window.Show();Application.DoEvents();var view=(NamWindow)typeof(StudioWindow).GetField("nam",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window);var pending=new TaskCompletionSource<bool>();var work=(Task)typeof(NamWindow).GetMethod("Work",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(view,new object[]{new Func<Task>(()=>pending.Task)});Require(window.IsBusy);Require(!window.SelectSectionAsync(true).GetAwaiter().GetResult()&&!window.FirmwareVisible);window.Close();Require(!window.IsDisposed&&window.Visible);pending.SetResult(true);Pump(work);Require(!window.IsBusy&&window.SelectSectionAsync(true).GetAwaiter().GetResult());window.Close();Require(window.IsDisposed&&StudioUsbGate.Owner=="");}});
  test("firmware_transfer_blocks_tab_change_and_window_close",()=>{using(var window=new StudioWindow(true)){window.ShowInTaskbar=false;window.StartPosition=FormStartPosition.Manual;window.Location=new System.Drawing.Point(-25000,-25000);window.Show();Application.DoEvents();Require(window.SelectSectionAsync(true).GetAwaiter().GetResult());var pane=typeof(StudioWindow).GetField("firmware",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window);var engine=new EngineSession(s=>{},()=>{},p=>{});Field(engine,"transferring",true);Field(pane,"engine",engine);Require(window.IsBusy&&!window.SelectSectionAsync(false).GetAwaiter().GetResult());window.Close();Require(!window.IsDisposed);Field(engine,"transferring",false);Require(window.SelectSectionAsync(false).GetAwaiter().GetResult());window.Close();Require(window.IsDisposed);}});
  test("default_output_is_minus5_without_changing_input",()=>{Require(NamWindow.DefaultOutputDb==-5);var original=NamCapture.AudioPayload(NamCapture.Read(source).Wave);var adjusted=NamCapture.AudioPayload(NamCapture.Read(source,-5).Wave);int offset=60*4;Require(original.Take(offset).SequenceEqual(adjusted.Take(offset))&&original.Skip(offset+4).SequenceEqual(adjusted.Skip(offset+4)));double ratio=BitConverter.ToSingle(adjusted,offset)/BitConverter.ToSingle(original,offset);Require(Math.Abs(ratio-Math.Pow(10,-5.0/20))<1e-7);});
  File.WriteAllText(Path.Combine(folder,"results.json"),new JavaScriptSerializer().Serialize(new{status=failed==0?"PASS_LOCAL_ONLY":"FAIL",cases=results,USB_opened=false,SDK_started=false,firmware_written=false,physical_unified_app_tested=false}));return failed==0?0:1;
 }
}
